// Data sub-tab of a table tab: server-side paging (LIMIT/OFFSET generated by the server), header
// sorting (click cycles asc → desc → off, shift-click adds a column), the filter bar, and staged
// editing when the table has a primary key: double-click / Enter edits a cell (NULL button),
// "+ Row" stages an insert, Delete / "Delete rows" stages deletions. The pending bar shows
// "N pending · Preview SQL · Discard · Commit ⌘S"; Commit sends every edit in one applyEdits call
// through the safety confirmation. Paging, sorting, filtering or refreshing with pending edits
// asks first (Beekeeper silently drops them; we do not). The count of staged edits is reported to
// the workspace store, so closing the tab, closing others, switching projects or editing the
// connection ask too; "Discard" answered there arrives as `discardEpoch` and drops them here.
//
// Paging: previous / next, a page number field (Enter jumps), rows per page. A large unfiltered
// table shows an estimated total ("of ~1.2M"); "Count" runs an exact COUNT(*) on demand.
//
// Filters: the filter rows combine with AND or OR (`filterJoin`, sent only for OR between two or
// more rows; the raw WHERE stays ANDed server-side) and the whole-table export carries the same
// filters, join, WHERE and sort as the grid.
//
// Row detail (toolbar "Detail" / Space in the grid): a side panel with every column of the focused
// row; its fields edit in place into the same staged edits as the cells (see grid/RowDetailPanel).
//
// Both toolbars are containers: labels collapse to icons in narrow panes (assistant open) and the
// right-hand groups (export + paging, Discard + Commit) wrap to a second row as a unit, so they
// never end up under the assistant or past the window edge.

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Code2,
  Download,
  Hash,
  Loader2,
  Lock,
  PanelRight,
  Plus,
  RefreshCw,
  Trash2
} from 'lucide-react'
import {
  isBinaryCell,
  type DataCell,
  type DataColumnMeta,
  type DataFilterJoin,
  type DataProject,
  type DataSort,
  type DataTableDetails,
  type DataTableRowsResponse,
  type SqlDialect
} from '@shared/data-projects/types'
import { qualifiedSqlName } from '@shared/sql'
import { dataProjectsApi } from '@/api/data-projects-api'
import {
  errorMessage,
  isCredentialsRequiredError
} from '@/components/data-projects/data-project-ui'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from '@/components/ui/dropdown-menu'
import { ShortcutHint } from '@/components/ui/shortcut-hint'
import { copyTextToClipboard } from '@/lib/clipboard'
import { toast } from '@/lib/toast'
import { cn } from '@/lib/utils'
import { useDataProjectStore } from '@/stores/useDataProjectStore'
import { useDataWorkspaceStore, type DataTableTab } from '@/stores/useDataWorkspaceStore'
import { ResultGrid, type ResultGridEditing, type ResultGridHandle } from '../grid/ResultGrid'
import { useRowDetailOpen } from '../grid/row-detail'
import { DATA_TABLE_COMMAND_EVENT, type DataTableCommandDetail } from '../DataProjectWorkspaceHost'
import { runWithConfirmation } from '../shared/confirm'
import { FULL_EXPORT_FORMATS, saveVisibleResults, startFullExport } from '../shared/export-actions'
import { formatCount, formatDuration } from '../shared/format-utils'
import { SqlText } from '../shared/SqlText'
import { FilterBar } from './FilterBar'
import {
  addValueFilter,
  effectiveFilterJoin,
  filterJoinField,
  newFilterDraft,
  toDataFilters,
  type FilterDraft
} from './filters'
import { newQueryId } from './query-runner'
import {
  addStagedInsert,
  displayRows,
  emptyStagedEdits,
  pendingCount,
  removeStagedInsert,
  stageCellEdit,
  stageInsertValue,
  toggleStagedDeletes,
  toRowEdits,
  type StagedEdits
} from './staged-edits'

const PAGE_SIZES: readonly number[] = [50, 100, 300, 500, 1000]

/** The exact row count of a table (no filters): `SELECT COUNT(*)` through the normal gate. */
async function countTableRows(
  project: DataProject,
  dialect: SqlDialect,
  tab: DataTableTab,
  queryId: string
): Promise<number | null> {
  const ref = tab.ref
  const response = await runWithConfirmation((confirmToken) =>
    dataProjectsApi.execute({
      dataProjectId: project.id,
      queryId,
      text: `SELECT COUNT(*) FROM ${qualifiedSqlName(ref, dialect)}`,
      ...(ref.database ? { database: ref.database } : {}),
      limit: null,
      ...(confirmToken ? { confirmToken } : {}),
      source: 'table',
      stopOnError: true
    })
  )
  if (response.status !== 'ok') return null
  const statement = response.statements[0]
  if (statement?.error) throw new Error(statement.error.message)
  const cell = statement?.output?.kind === 'rows' ? statement.output.rows[0]?.[0] : null
  const count = typeof cell === 'number' ? cell : typeof cell === 'string' ? Number(cell) : NaN
  return Number.isFinite(count) ? count : null
}

export interface TableDataViewProps {
  project: DataProject
  dialect: SqlDialect
  tab: DataTableTab
  /** Describe result (null while loading / failed): primary key and kind fallback. */
  details: DataTableDetails | null
}

const nextSort = (sort: DataSort[], column: string, additive: boolean): DataSort[] => {
  const current = sort.find((s) => s.column === column)
  const next: DataSort | null = !current
    ? { column, direction: 'asc' }
    : current.direction === 'asc'
      ? { column, direction: 'desc' }
      : null
  if (!additive) return next ? [next] : []
  const rest = sort.filter((s) => s.column !== column)
  return next ? [...rest, next] : rest
}

export function TableDataView({
  project,
  dialect,
  tab,
  details
}: TableDataViewProps): React.JSX.Element {
  const ref = tab.ref
  const refKey = JSON.stringify([ref.database ?? '', ref.schema ?? '', ref.name])
  const [pageSize, setPageSize] = useState(100)
  const [page, setPage] = useState(0)
  const [sort, setSort] = useState<DataSort[]>([])
  const [drafts, setDrafts] = useState<FilterDraft[]>([])
  const [join, setJoin] = useState<DataFilterJoin>('and')
  const [where, setWhere] = useState('')
  const [showWhere, setShowWhere] = useState(false)
  const [applied, setApplied] = useState<{
    filters: FilterDraft[]
    join: DataFilterJoin
    where: string
  }>({
    filters: [],
    join: 'and',
    where: ''
  })
  const [response, setResponse] = useState<DataTableRowsResponse | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [reloadKey, setReloadKey] = useState(0)
  // An import into this project reloads the open page (useDataWorkspaceStore.notifyTableDataChanged).
  const dataVersion = useDataWorkspaceStore((s) => s.tableDataVersion[project.id] ?? 0)
  const [staged, setStagedState] = useState<StagedEdits>(emptyStagedEdits)
  // The staged edits as of the last change, ahead of the render: ⌘S in a row detail field stages
  // that field and commits in the same keydown, so Commit must see it before React re-renders.
  const stagedRef = useRef(staged)
  const setStaged = useCallback((update: StagedEdits | ((s: StagedEdits) => StagedEdits)) => {
    const next = typeof update === 'function' ? update(stagedRef.current) : update
    stagedRef.current = next
    setStagedState(next)
  }, [])
  const [selectedRows, setSelectedRows] = useState<number[]>([])
  const [preview, setPreview] = useState<{ sql: string[] | null; error?: string } | null>(null)
  const [committing, setCommitting] = useState(false)
  const [guardAction, setGuardAction] = useState<{ run: () => void } | null>(null)
  const [showSql, setShowSql] = useState(false)
  const [pageDraft, setPageDraft] = useState<string | null>(null)
  const [exactCount, setExactCount] = useState<{ key: string; total: number } | null>(null)
  const [counting, setCounting] = useState(false)
  const seqRef = useRef(0)
  const queryIdRef = useRef<string | null>(null)
  const countQueryRef = useRef<string | null>(null)
  const gridRef = useRef<ResultGridHandle>(null)
  const [rowDetailOpen, setRowDetailOpen] = useRowDetailOpen()

  const appliedFilters = useMemo(() => toDataFilters(applied.filters), [applied.filters])
  const appliedJoin = filterJoinField(appliedFilters, applied.join)

  const load = useCallback(async () => {
    const seq = ++seqRef.current
    if (queryIdRef.current) void dataProjectsApi.cancel(queryIdRef.current).catch(() => undefined)
    const queryId = newQueryId()
    queryIdRef.current = queryId
    setLoading(true)
    setError(null)
    try {
      const res = await dataProjectsApi.tableRows({
        dataProjectId: project.id,
        queryId,
        ref: ref,
        ...(appliedFilters.length ? { filters: appliedFilters } : {}),
        ...appliedJoin,
        ...(applied.where.trim() ? { where: applied.where.trim() } : {}),
        ...(sort.length ? { orderBy: sort } : {}),
        limit: pageSize,
        offset: page * pageSize
      })
      if (seq !== seqRef.current) return
      setResponse(res)
    } catch (err) {
      if (seq !== seqRef.current) return
      const message = errorMessage(err, 'Could not load the rows')
      setError(message)
      if (isCredentialsRequiredError(err))
        useDataProjectStore.getState().openCredentialsPrompt(project.id, message)
    } finally {
      if (seq === seqRef.current) {
        setLoading(false)
        queryIdRef.current = null
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    project.id,
    refKey,
    appliedFilters,
    appliedJoin.filterJoin,
    applied.where,
    sort,
    pageSize,
    page
  ])

  useEffect(() => {
    void load()
  }, [load, reloadKey, dataVersion])

  useEffect(
    () => () => {
      seqRef.current++
      if (queryIdRef.current) void dataProjectsApi.cancel(queryIdRef.current).catch(() => undefined)
      if (countQueryRef.current)
        void dataProjectsApi.cancel(countQueryRef.current).catch(() => undefined)
    },
    []
  )

  const columns: DataColumnMeta[] = useMemo(
    () =>
      response?.result.columns ??
      details?.columns.map((c) => ({ name: c.name, type: c.type })) ??
      [],
    [response, details]
  )
  const colNames = useMemo(() => columns.map((c) => c.name), [columns])
  const primaryKey = response?.primaryKey?.length
    ? response.primaryKey
    : (details?.primaryKey ?? [])
  const kind = details?.kind ?? ref.kind ?? 'table'
  const editBlock =
    project.safeMode === 'read-only'
      ? 'Read-only mode: editing is off'
      : project.engine === 'clickhouse'
        ? 'ClickHouse tables are read-only here (UPDATE/DELETE are asynchronous mutations)'
        : kind !== 'table'
          ? `A ${kind.replace('_', ' ')} is read-only`
          : primaryKey.length === 0
            ? 'No primary key: rows cannot be identified for editing'
            : null
  const editable = !editBlock && !!response
  const pageRows = response?.result.rows
  const display = useMemo(
    () => displayRows(pageRows ?? [], colNames, primaryKey, staged),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [pageRows, colNames, primaryKey.join('\u0000'), staged]
  )
  const pending = pendingCount(staged)

  // The workspace asks before closing this tab / leaving the project while edits are staged.
  useEffect(() => {
    useDataWorkspaceStore.getState().setStagedEditCount(tab.id, pending)
  }, [tab.id, pending])
  useEffect(() => () => useDataWorkspaceStore.getState().setStagedEditCount(tab.id, 0), [tab.id])
  // "Discard" answered in the workspace's leave question.
  const discardEpoch = useDataWorkspaceStore((s) => s.discardEpoch[project.id] ?? 0)
  const seenDiscardEpoch = useRef(discardEpoch)
  useEffect(() => {
    if (discardEpoch === seenDiscardEpoch.current) return
    seenDiscardEpoch.current = discardEpoch
    setStaged(emptyStagedEdits())
    setPreview(null)
  }, [discardEpoch, setStaged])

  const guarded = (action: () => void): void => {
    if (pending > 0) setGuardAction({ run: action })
    else action()
  }

  // ⌘R / ⌘F from the data client (DataProjectView): refresh this page or focus the filter bar,
  // only while this table tab is the active one and shows its data.
  const rootRef = useRef<HTMLDivElement>(null)
  const guardedRef = useRef(guarded)
  guardedRef.current = guarded
  useEffect(() => {
    const onCommand = (event: Event): void => {
      const detail = (event as CustomEvent<DataTableCommandDetail>).detail
      if (detail?.projectId !== project.id) return
      if (useDataWorkspaceStore.getState().getActiveTab(project.id)?.id !== tab.id) return
      if (tab.view !== 'data' || !rootRef.current) return
      event.preventDefault()
      if (detail.command === 'refresh') {
        guardedRef.current(() => setReloadKey((k) => k + 1))
        return
      }
      const root = rootRef.current
      const input = root.querySelector<HTMLElement>('[data-testid="data-project-filter-value"]')
      if (input) input.focus()
      else root.querySelector<HTMLElement>('[data-testid="data-project-filter-add"]')?.click()
    }
    window.addEventListener(DATA_TABLE_COMMAND_EVENT, onCommand)
    return () => window.removeEventListener(DATA_TABLE_COMMAND_EVENT, onCommand)
  }, [project.id, tab.id, tab.view])

  const editing: ResultGridEditing | undefined = editable
    ? {
        isEditable: (row, col) => {
          const info = display.info[row]
          if (!info) return false
          if (info.kind === 'existing') return !isBinaryCell(pageRows?.[info.index]?.[col] ?? null)
          return true
        },
        onCommitEdit: (row, col, value) => {
          const info = display.info[row]
          if (!info || !pageRows) return
          setStaged((s) =>
            info.kind === 'existing'
              ? stageCellEdit(s, pageRows[info.index], colNames[col], value, colNames, primaryKey)
              : stageInsertValue(s, info.id, colNames[col], value)
          )
        },
        rowState: (row) => {
          const info = display.info[row]
          if (!info) return null
          if (info.kind === 'inserted') return 'inserted'
          return info.key && staged.deletes[info.key] ? 'deleted' : null
        },
        cellState: (row, col) => {
          const info = display.info[row]
          if (!info) return null
          if (info.kind === 'inserted') {
            const ins = staged.inserts.find((i) => i.id === info.id)
            return ins && !(colNames[col] in ins.values) ? 'default' : null
          }
          return info.key &&
            staged.updates[info.key] &&
            colNames[col] in staged.updates[info.key].changes
            ? 'modified'
            : null
        },
        onDeleteRows: (rows) => deleteRows(rows)
      }
    : undefined

  const deleteRows = (rows: number[]): void => {
    if (!pageRows) return
    setStaged((s) => {
      let next = s
      const existing: DataCell[][] = []
      for (const r of rows) {
        const info = display.info[r]
        if (!info) continue
        if (info.kind === 'inserted') next = removeStagedInsert(next, info.id)
        else existing.push(pageRows[info.index])
      }
      return existing.length ? toggleStagedDeletes(next, existing, colNames, primaryKey) : next
    })
  }

  const addRow = (): void => {
    const { staged: next } = addStagedInsert(stagedRef.current)
    setStaged(next)
    const index = (pageRows?.length ?? 0) + next.inserts.length - 1
    requestAnimationFrame(() => gridRef.current?.selectRow(index))
  }

  const discard = (): void => {
    setStaged(emptyStagedEdits())
    setPreview(null)
  }

  const commit = async (): Promise<void> => {
    const current = stagedRef.current
    if (!pendingCount(current) || committing) return
    const edits = toRowEdits(current)
    setCommitting(true)
    try {
      const res = await runWithConfirmation((confirmToken) =>
        dataProjectsApi.applyEdits({
          dataProjectId: project.id,
          ref: ref,
          edits,
          ...(confirmToken ? { confirmToken } : {})
        })
      )
      if (res.status === 'ok') {
        toast.success(
          `${formatCount(res.affectedRows)} ${res.affectedRows === 1 ? 'row' : 'rows'} affected (${res.statements.length} ${res.statements.length === 1 ? 'statement' : 'statements'})`
        )
        setStaged(emptyStagedEdits())
        setPreview(null)
        setReloadKey((k) => k + 1)
      } else if (res.status === 'confirmation_required') {
        toast.error('The server asked for confirmation again; nothing was committed.')
      }
    } catch (err) {
      toast.error(`Commit failed, nothing was changed: ${errorMessage(err)}`)
    } finally {
      setCommitting(false)
    }
  }

  const openPreview = async (): Promise<void> => {
    setPreview({ sql: null })
    try {
      const sql = await dataProjectsApi.previewEdits(project.id, ref, toRowEdits(staged))
      setPreview({ sql })
    } catch (err) {
      setPreview({ sql: [], error: errorMessage(err, 'Could not build the SQL') })
    }
  }

  const applyFilters = (): void =>
    guarded(() => {
      setApplied({ filters: drafts, join, where: showWhere ? where : '' })
      setPage(0)
    })

  const filterByValue = (column: string, value: DataCell): void => {
    const draft =
      value === null
        ? newFilterDraft(column, 'is null')
        : newFilterDraft(column, '=', isBinaryCell(value) ? `0x${value.hex}` : String(value))
    const next = addValueFilter(drafts, join, draft)
    guarded(() => {
      setDrafts(next.drafts)
      setJoin(next.join)
      setApplied({ filters: next.drafts, join: next.join, where: showWhere ? where : '' })
      setPage(0)
      if (next.replaced) toast.info(`Now filtering by ${column} only: it replaced the OR filters`)
    })
  }

  const draftFilters = toDataFilters(drafts)
  const filtersDirty =
    JSON.stringify(draftFilters) !== JSON.stringify(appliedFilters) ||
    effectiveFilterJoin(draftFilters, join) !== effectiveFilterJoin(appliedFilters, applied.join) ||
    (showWhere ? where : '') !== applied.where

  // An exact count asked for with "Count" holds until the rows are reloaded (refresh, commit) or
  // the filters change.
  const countKey = JSON.stringify([
    refKey,
    appliedFilters,
    appliedJoin.filterJoin ?? 'and',
    applied.where,
    reloadKey
  ])
  const exact = exactCount?.key === countKey ? exactCount.total : null
  const total = exact ?? response?.totalRows ?? null
  const estimated = exact === null && !!response?.totalIsEstimate
  const offset = page * pageSize
  const shown = pageRows?.length ?? 0
  const hasNext =
    !!response &&
    (exact !== null
      ? offset + shown < exact
      : response.result.truncated ||
        (total !== null && !estimated && offset + shown < total) ||
        (total === null && shown === pageSize))
  const rangeLabel = shown
    ? `rows ${formatCount(offset + 1)}–${formatCount(offset + shown)}${
        total !== null ? ` of ${estimated ? '~' : ''}${formatCount(total)}` : ''
      }`
    : total !== null && offset === 0
      ? `0 of ${estimated ? '~' : ''}${formatCount(total)} rows`
      : 'no rows'
  const pageCount = total !== null && !estimated ? Math.max(1, Math.ceil(total / pageSize)) : null

  const goToPage = (text: string): void => {
    setPageDraft(null)
    const n = Number.parseInt(text, 10)
    if (!Number.isFinite(n)) return
    const target = Math.max(0, (pageCount !== null ? Math.min(n, pageCount) : n) - 1)
    if (target !== page) guarded(() => setPage(target))
  }

  const countExactly = async (): Promise<void> => {
    if (counting) return
    const queryId = newQueryId()
    countQueryRef.current = queryId
    setCounting(true)
    try {
      const count = await countTableRows(project, dialect, tab, queryId)
      if (countQueryRef.current !== queryId) return
      if (count !== null) setExactCount({ key: countKey, total: count })
    } catch (err) {
      if (countQueryRef.current === queryId)
        toast.error(`Could not count the rows: ${errorMessage(err)}`)
    } finally {
      if (countQueryRef.current === queryId) {
        countQueryRef.current = null
        setCounting(false)
      }
    }
  }

  const onKeyDown = (e: React.KeyboardEvent): void => {
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's') {
      e.preventDefault()
      if (pendingCount(stagedRef.current)) void commit()
    }
  }

  return (
    <div
      ref={rootRef}
      className="flex min-h-0 flex-1 flex-col"
      onKeyDown={onKeyDown}
      data-testid="data-project-table-data"
    >
      <div className="@container/tdv flex min-h-9 shrink-0 flex-wrap items-center gap-1 border-b border-border px-2 py-1">
        <Button
          variant="ghost"
          size="icon-sm"
          onClick={() => guarded(() => setReloadKey((k) => k + 1))}
          title="Refresh"
          data-testid="data-project-table-refresh"
        >
          {loading ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <RefreshCw className="h-3.5 w-3.5" />
          )}
        </Button>
        {editable ? (
          <>
            <Button
              variant="ghost"
              size="sm"
              onClick={addRow}
              title="Add a row (staged until Commit)"
              data-testid="data-project-table-add-row"
            >
              <Plus className="h-3.5 w-3.5" />
              <span className="hidden @[560px]/tdv:inline">Row</span>
            </Button>
            <Button
              variant="ghost"
              size="sm"
              disabled={!selectedRows.length}
              onClick={() => deleteRows(selectedRows)}
              title="Delete the selected rows (staged until Commit)"
              data-testid="data-project-table-delete-rows"
            >
              <Trash2 className="h-3.5 w-3.5" />
              <span className="hidden @[560px]/tdv:inline">Delete</span>
            </Button>
          </>
        ) : (
          editBlock && (
            <span
              className="flex min-w-0 items-center gap-1 px-1 text-[11px] text-muted-foreground"
              title={editBlock}
              data-testid="data-project-table-readonly"
            >
              <Lock className="h-3 w-3 shrink-0" />
              <span className="hidden truncate @[720px]/tdv:inline">{editBlock}</span>
            </span>
          )
        )}
        <div className="ml-auto flex shrink-0 items-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            className={cn(rowDetailOpen && 'bg-accent')}
            onClick={() => {
              setRowDetailOpen(!rowDetailOpen)
              gridRef.current?.focus()
            }}
            aria-pressed={rowDetailOpen}
            title="Row detail: every column of the selected row, editable in place (Space)"
            data-testid="data-project-table-row-detail"
          >
            <PanelRight className="h-3.5 w-3.5" />
            <span className="hidden @[640px]/tdv:inline">Detail</span>
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className={cn(showSql && 'bg-accent')}
            onClick={() => setShowSql((v) => !v)}
            title="Show the generated SELECT"
            data-testid="data-project-table-show-sql"
          >
            <Code2 className="h-3.5 w-3.5" />
            <span className="hidden @[640px]/tdv:inline">SQL</span>
          </Button>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                title="Export rows"
                data-testid="data-project-table-export"
              >
                <Download className="h-3.5 w-3.5" />
                <span className="hidden @[640px]/tdv:inline">Export</span>
                <ChevronDown className="h-3 w-3" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-[230px]">
              <DropdownMenuLabel>Whole table (current filters and sort)</DropdownMenuLabel>
              {FULL_EXPORT_FORMATS.map((f) => (
                <DropdownMenuItem
                  key={f.format}
                  onSelect={() =>
                    void startFullExport({
                      dataProjectId: project.id,
                      source: {
                        kind: 'table',
                        ref: ref,
                        ...(appliedFilters.length ? { filters: appliedFilters } : {}),
                        ...appliedJoin,
                        ...(applied.where.trim() ? { where: applied.where.trim() } : {}),
                        ...(sort.length ? { orderBy: sort } : {})
                      },
                      format: f.format
                    })
                  }
                  data-testid={`data-project-table-export-${f.format}`}
                >
                  Export as {f.label}…
                </DropdownMenuItem>
              ))}
              <DropdownMenuSeparator />
              <DropdownMenuLabel>This page ({formatCount(shown)} rows)</DropdownMenuLabel>
              {(['csv', 'json', 'sql'] as const).map((format) => (
                <DropdownMenuItem
                  key={format}
                  disabled={!response}
                  onSelect={() =>
                    response &&
                    void saveVisibleResults(
                      columns,
                      response.result.rows,
                      format,
                      `${ref.name}-page-${page + 1}`,
                      {
                        dialect,
                        table: { name: ref.name, schema: ref.schema, database: ref.database }
                      }
                    )
                  }
                >
                  Save page as {format === 'sql' ? 'SQL INSERT' : format.toUpperCase()}…
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
        {/* Paging is its own unit: in a very narrow pane it takes a row of its own. */}
        <div className="ml-auto flex shrink-0 items-center gap-1">
          <select
            value={pageSize}
            onChange={(e) => {
              const size = Number(e.target.value)
              guarded(() => {
                setPageSize(size)
                setPage(0)
              })
            }}
            className="h-7 rounded-md border border-input bg-background px-1.5 text-[12px]"
            data-testid="data-project-table-page-size"
            title="Rows per page"
          >
            {PAGE_SIZES.map((n) => (
              <option key={n} value={n}>
                {n} / page
              </option>
            ))}
          </select>
          <Button
            variant="ghost"
            size="icon-sm"
            disabled={page === 0 || loading}
            onClick={() => guarded(() => setPage((p) => Math.max(0, p - 1)))}
            title="Previous page"
            data-testid="data-project-table-prev"
          >
            <ChevronLeft className="h-3.5 w-3.5" />
          </Button>
          <input
            value={pageDraft ?? String(page + 1)}
            onChange={(e) => setPageDraft(e.target.value.replace(/[^\d]/g, ''))}
            onFocus={(e) => e.currentTarget.select()}
            onBlur={() => setPageDraft(null)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault()
                goToPage(e.currentTarget.value)
                e.currentTarget.blur()
              } else if (e.key === 'Escape') {
                e.currentTarget.blur()
              }
            }}
            inputMode="numeric"
            aria-label="Page"
            title={
              pageCount !== null
                ? `Page (of ${formatCount(pageCount)}) · Enter jumps`
                : 'Page · Enter jumps'
            }
            data-testid="data-project-table-page"
            className="h-7 w-11 rounded-md border border-input bg-transparent px-1 text-center text-[12px] tabular-nums outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
          />
          <span
            className="hidden min-w-0 truncate text-center text-[11px] tabular-nums text-muted-foreground @[480px]/tdv:inline"
            title={rangeLabel}
            data-testid="data-project-table-range"
          >
            {rangeLabel}
          </span>
          {estimated && (
            <Button
              variant="ghost"
              size="icon-sm"
              disabled={counting}
              onClick={() => void countExactly()}
              title="The total is an estimate: count the rows exactly (SELECT COUNT(*))"
              data-testid="data-project-table-count"
            >
              {counting ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Hash className="h-3.5 w-3.5" />
              )}
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon-sm"
            disabled={!hasNext || loading}
            onClick={() => guarded(() => setPage((p) => p + 1))}
            title="Next page"
            data-testid="data-project-table-next"
          >
            <ChevronRight className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>
      <FilterBar
        columns={colNames}
        filters={drafts}
        onFiltersChange={setDrafts}
        join={join}
        onJoinChange={setJoin}
        where={where}
        onWhereChange={setWhere}
        showWhere={showWhere}
        onShowWhereChange={setShowWhere}
        onApply={applyFilters}
        onClear={() => {
          setDrafts([])
          setJoin('and')
          setWhere('')
          setShowWhere(false)
          if (appliedFilters.length || applied.where) {
            guarded(() => {
              setApplied({ filters: [], join: 'and', where: '' })
              setPage(0)
            })
          }
        }}
        dirty={filtersDirty}
      />
      {showSql && response?.sql && (
        <div
          className="max-h-28 shrink-0 overflow-auto border-b border-border bg-card px-2 py-1"
          data-testid="data-project-table-sql"
        >
          <SqlText text={response.sql} dialect={dialect} />
        </div>
      )}
      {error && (
        <div
          className="flex shrink-0 items-start gap-2 border-b border-border bg-red-500/10 px-3 py-1.5 text-[12px] text-red-600 dark:text-red-400"
          data-testid="data-project-table-error"
        >
          <span className="min-w-0 flex-1 whitespace-pre-wrap break-words">{error}</span>
          <Button
            variant="outline"
            size="sm"
            className="h-6"
            onClick={() => setReloadKey((k) => k + 1)}
          >
            Retry
          </Button>
        </div>
      )}
      <div className="relative flex min-h-0 flex-1 flex-col">
        {response || !loading ? (
          <ResultGrid
            ref={gridRef}
            columns={columns}
            rows={display.rows}
            rowNumberOffset={offset}
            sort={sort}
            onSortColumn={(column, additive) =>
              guarded(() => {
                setSort((s) => nextSort(s, column, additive))
                setPage(0)
              })
            }
            onFilterByValue={filterByValue}
            dialect={dialect}
            insertTable={{ name: ref.name, schema: ref.schema, database: ref.database }}
            editing={editing}
            rowDetail={{
              open: rowDetailOpen,
              onOpenChange: setRowDetailOpen,
              keyColumns: primaryKey
            }}
            onSelectionChange={setSelectedRows}
            emptyMessage={
              appliedFilters.length || applied.where
                ? 'No rows match the filters'
                : 'The table is empty'
            }
            data-testid="data-project-result-grid"
          />
        ) : null}
        {loading && (
          <div
            className="pointer-events-none absolute inset-0 z-30 flex items-center justify-center bg-background/40"
            data-testid="data-project-table-loading"
          >
            <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
          </div>
        )}
      </div>
      {pending > 0 && (
        <div
          className="@container/pending flex min-h-9 shrink-0 flex-wrap items-center gap-x-2 gap-y-1 border-t border-amber-500/40 bg-amber-500/10 px-3 py-1 text-[12px]"
          data-testid="data-project-pending-bar"
        >
          <span
            className="font-medium text-amber-700 dark:text-amber-300"
            data-testid="data-project-pending-count"
          >
            {pending} pending {pending === 1 ? 'change' : 'changes'}
          </span>
          <span className="hidden text-muted-foreground @[560px]/pending:inline">
            {Object.keys(staged.updates).length} edited · {staged.inserts.length} new ·{' '}
            {Object.keys(staged.deletes).length} deleted
          </span>
          <div className="ml-auto flex shrink-0 items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => void openPreview()}
              title="Preview the SQL of the pending changes"
              data-testid="data-project-pending-preview"
            >
              <span className="@[360px]/pending:hidden">SQL</span>
              <span className="hidden @[360px]/pending:inline">Preview SQL</span>
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={discard}
              disabled={committing}
              data-testid="data-project-pending-discard"
            >
              Discard
            </Button>
            <Button
              size="sm"
              onClick={() => void commit()}
              disabled={committing}
              data-testid="data-project-pending-commit"
            >
              {committing && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
              Commit
              <ShortcutHint label="⌘S" />
            </Button>
          </div>
        </div>
      )}
      {response && !pending && (
        <div className="flex h-6 shrink-0 items-center gap-2 border-t border-border bg-card px-2 text-[11px] text-muted-foreground">
          <span>{formatDuration(response.durationMs)}</span>
          {primaryKey.length > 0 && <span>· key: {primaryKey.join(', ')}</span>}
        </div>
      )}
      <Dialog open={preview !== null} onOpenChange={(open) => !open && setPreview(null)}>
        <DialogContent
          className="flex max-h-[80vh] max-w-2xl flex-col"
          data-testid="data-project-preview-dialog"
        >
          <DialogHeader>
            <DialogTitle className="text-[15px]">Pending changes as SQL</DialogTitle>
            <DialogDescription className="text-[12px]">
              Runs in one transaction when you commit. Nothing has been sent yet.
            </DialogDescription>
          </DialogHeader>
          <div className="min-h-[120px] flex-1 overflow-auto rounded-md border border-border bg-muted/40 p-2">
            {preview?.sql === null ? (
              <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            ) : preview?.error ? (
              <div className="text-[12px] text-red-600 dark:text-red-400">{preview.error}</div>
            ) : (
              <SqlText
                text={(preview?.sql ?? []).map((s) => `${s};`).join('\n')}
                dialect={dialect}
                data-testid="data-project-preview-sql"
              />
            )}
          </div>
          <DialogFooter className="gap-2">
            <Button
              variant="outline"
              size="sm"
              disabled={!preview?.sql?.length}
              onClick={async () => {
                if (await copyTextToClipboard((preview?.sql ?? []).map((s) => `${s};`).join('\n')))
                  toast.success('SQL copied')
              }}
            >
              Copy
            </Button>
            <Button
              size="sm"
              disabled={committing}
              onClick={() => void commit()}
              data-testid="data-project-preview-commit"
            >
              Commit
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <AlertDialog
        open={guardAction !== null}
        onOpenChange={(open) => !open && setGuardAction(null)}
      >
        <AlertDialogContent size="sm" data-testid="data-project-discard-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[15px]">
              Discard {pending} pending {pending === 1 ? 'change' : 'changes'}?
            </AlertDialogTitle>
            <AlertDialogDescription className="text-[12px]">
              Reloading the rows drops the staged edits. Commit them first to keep them.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep editing</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => {
                const action = guardAction
                setGuardAction(null)
                discard()
                action?.run()
              }}
              data-testid="data-project-discard-confirm"
            >
              Discard
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
